use deskbox_reconstructed::media::{prepare_background, MediaBackground};
use std::{fs,path::PathBuf,process::Command};
fn temp()->PathBuf { let p=std::env::temp_dir().join(format!("deskbox-media-test-{}",uuid::Uuid::new_v4()));fs::create_dir_all(&p).unwrap();p }
#[test] fn rejects_unknown_without_staging() {let p=temp();let s=p.join("bad.txt");fs::write(&s,b"x").unwrap();let cache=p.join("cache");assert!(prepare_background(&s,&cache,&p.join("missing.exe")).is_err());assert!(!cache.exists());fs::remove_dir_all(p).unwrap();}
#[test] fn rejects_invalid_mode_and_outside_managed_paths(){let p=temp();let m=MediaBackground{kind:"video".into(),original:p.join("missing.mp4").to_string_lossy().into(),eco:None,poster:p.join("poster.png").to_string_lossy().into(),mode:"eco".into()};assert!(m.validate_mode("invalid",&p).is_err());assert!(m.validate_mode("eco",&p).is_err());fs::remove_dir_all(p).unwrap();}
#[test] fn failed_decode_cleans_staging(){let Some(ff)=std::env::var_os("DESKBOX_FFMPEG_TEST") else{return};let p=temp();let s=p.join("bad.mp4");fs::write(&s,b"invalid").unwrap();let cache=p.join("cache");assert!(prepare_background(&s,&cache,&PathBuf::from(ff)).is_err());assert_eq!(fs::read_dir(&cache).unwrap().count(),0);fs::remove_dir_all(p).unwrap();}
#[test] fn real_video_preserves_original_and_produces_bounded_muted_eco(){let Some(ff)=std::env::var_os("DESKBOX_FFMPEG_TEST") else{return};let ff=PathBuf::from(ff);let p=temp();let s=p.join("source.mp4");assert!(Command::new(&ff).args(["-v","error","-f","lavfi","-i","testsrc2=size=1280x720:rate=60","-f","lavfi","-i","sine=frequency=440","-t","0.5","-c:v","libx264","-threads","2","-pix_fmt","yuv420p","-c:a","aac","-y"]).arg(&s).status().unwrap().success());let bytes=fs::read(&s).unwrap();let m=prepare_background(&s,&p.join("cache"),&ff).unwrap();assert_eq!(m.mode,"eco");assert_eq!(fs::read(&m.original).unwrap(),bytes);m.validate_mode("original",&p.join("cache")).unwrap();m.validate_mode("eco",&p.join("cache")).unwrap();let out=Command::new(&ff).args(["-hide_banner","-i"]).arg(m.eco.unwrap()).output().unwrap();let info=String::from_utf8_lossy(&out.stderr);assert!(info.contains("854x480"),"{info}");assert!(info.contains("30 fps"),"{info}");assert!(!info.contains("Audio:"),"{info}");assert!(info.contains("h264"),"{info}");assert!(fs::metadata(m.poster).unwrap().len()>0);fs::remove_dir_all(p).unwrap();}
#[test] fn real_gif_stays_animated_original(){let Some(ff)=std::env::var_os("DESKBOX_FFMPEG_TEST") else{return};let ff=PathBuf::from(ff);let p=temp();let s=p.join("source.gif");assert!(Command::new(&ff).args(["-v","error","-f","lavfi","-i","testsrc2=size=80x60:rate=10","-t","0.4","-threads","2","-y"]).arg(&s).status().unwrap().success());let bytes=fs::read(&s).unwrap();let m=prepare_background(&s,&p.join("cache"),&ff).unwrap();assert_eq!(m.kind,"gif");assert_eq!(m.mode,"original");assert!(m.eco.is_none());assert_eq!(fs::read(m.original).unwrap(),bytes);fs::remove_dir_all(p).unwrap();}
